        "$:/plugins/twpub/010c8e9ec74edf7d/text/000000008": {
            "role": "text",
            "title": "$:/plugins/twpub/010c8e9ec74edf7d/text/000000008",
            "type": "text/vnd.twpub",
            "text": "<div class=\"\"><div class=\"calibre1\"><div class=\"cbj_comments\"><p class=\"description\">你是否渴望突破阶层限制？是否希望下一代活得比你更自由、更有成就？</p></div></div></div>"
        },
        "$:/plugins/twpub/010c8e9ec74edf7d/text/000000009": {
            "role": "text",
            "title": "$:/plugins/twpub/010c8e9ec74edf7d/text/000000009",
